using System;
using System.Linq;
using NUnit.Framework;
namespace Brodun.Tests {
public sealed class Item40Tests:RulesTest {
 GameDefinitions Modern()=>Card70Catalog.Apply(Data);
 RunState NewRun(CharacterId hero=CharacterId.Warrior,params string[] ids){var run=new RunState(Modern(),hero,17);if(ids.Length>0){run.deck.Clear();foreach(var id in ids)run.AddCard(id);}return run;}
 BattleRuntime Start(RunState run,int extra=0,string node="r1"){
  run.ActiveRoom=node;var d=Modern();var odd=new EnemyDefinition("item-probe","probe",EnemyType.Normal,1,10000,0,"moss_slime",new[]{new IntentData(IntentType.Attack,0)});
  var b=new BattleRuntime(d,run,DungeonRuntime.Node(run,node),additionalEnemies:Enumerable.Repeat(odd,extra));b.Deck.Draw(10);b.Energy=6;
  foreach(var enemy in b.Enemies){enemy.CurrentHP=10000;enemy.Block=0;enemy.CurrentIntent=new IntentData(IntentType.Attack,0);}return b;
 }
 void Give(RunState r,params string[] ids){foreach(var id in ids)Assert.IsTrue(r.AddItem(id),id);}
 void Play(BattleRuntime b,string id,EnemyInstance target=null){var c=b.Deck.Hand.First(x=>x.CardId==id);var d=b.Definition(c);Assert.IsTrue(b.PlayCard(c.InstanceId,d.RequiresEnemyTarget?(target??b.Enemy).TargetId:null),id);}
 RoomRuntime Store(RunState run,EventKind kind=EventKind.Altar,string id="store"){run.ActiveRoom=id;return new RoomRuntime(Modern(),run,new RoomNode(id,RoomType.Event,2,50,Array.Empty<string>(),kind));}
 void Kill(BattleRuntime b,string id="W01"){foreach(var e in b.Enemies.Skip(1))e.CurrentHP=0;b.Enemy.CurrentHP=1;b.Enemy.Block=0;Play(b,id);Assert.AreEqual(BattleResult.Won,b.Result);}

 [Test] public void CatalogHasFortyPricedUniqueEffectsAndCorrectClassDistribution(){Assert.AreEqual(40,Item40Catalog.All.Count);Assert.AreEqual(40,Item40Catalog.All.Select(i=>i.Id).Distinct().Count());Assert.AreEqual(22,Item40Catalog.All.Count(i=>!i.Owner.HasValue));foreach(CharacterId hero in Enum.GetValues(typeof(CharacterId)))Assert.AreEqual(6,Item40Catalog.All.Count(i=>i.Owner==hero));foreach(var i in Item40Catalog.All){Assert.IsNotEmpty(i.Name);Assert.IsNotEmpty(i.Description);Assert.Greater(i.BuyPrice,i.SellPrice);Assert.AreEqual(i.BuyPrice/2,i.SellPrice);}}
 [Test] public void ItemOwnershipRejectsDuplicatesForeignClassesAndUnknownIds(){var r=NewRun();Assert.IsFalse(r.AddItem("bad"));Assert.IsFalse(r.AddItem("I23"));Assert.IsTrue(r.AddItem("I01"));Assert.IsFalse(r.AddItem("I01"));Assert.AreEqual(1,r.Items.Count);}
 [TestCase(EventKind.Shop)] [TestCase(EventKind.Altar)] public void EverySanctuaryProvidesBothCardAndItemStock(EventKind kind){foreach(CharacterId hero in Enum.GetValues(typeof(CharacterId))){var r=NewRun(hero);var room=Store(r,kind);Assert.AreEqual(3,room.Visit.Offers.Count);Assert.AreEqual(4,room.Visit.ItemOffers.Count);foreach(var offer in room.Visit.Offers){var card=room.Data.Card(offer.CardId);Assert.IsTrue(!card.Owner.HasValue||card.Owner==hero);Assert.AreEqual(SanctuaryPrices.CardBuy(card),offer.Price);}foreach(var offer in room.Visit.ItemOffers){var item=Item40Catalog.Find(offer.ItemId);Assert.IsTrue(!item.Owner.HasValue||item.Owner==hero);}Assert.IsTrue(room.Visit.ItemOffers.Any(o=>Item40Catalog.Find(o.ItemId).Owner==hero));}}
 [Test] public void FailedPurchaseIsAtomicAndSuccessfulPurchaseCannotRepeat(){var r=NewRun();var room=Store(r);int price=room.Visit.ItemOffers[0].Price;r.AddGold(price-1);Assert.IsFalse(room.BuyItem(0));Assert.AreEqual(price-1,r.Gold);Assert.AreEqual(0,r.Items.Count);r.AddGold(1);Assert.IsTrue(room.BuyItem(0));Assert.AreEqual(0,r.Gold);Assert.AreEqual(1,r.Items.Count);r.AddGold(price);Assert.IsFalse(room.BuyItem(0));Assert.AreEqual(price,r.Gold);}
 [Test] public void BuyingAndSellingAlwaysLosesGold(){var r=NewRun();var room=Store(r);var offer=room.Visit.ItemOffers[0];r.AddGold(1000);Assert.IsTrue(room.BuyItem(0));Assert.IsTrue(room.SellItem(offer.ItemId));Assert.AreEqual(1000-offer.Price+Item40Catalog.Find(offer.ItemId).SellPrice,r.Gold);Assert.IsFalse(room.SellItem(offer.ItemId));Assert.IsFalse(room.BuyItem(0));}
 [Test] public void ReentryPreservesStockPurchasesAndCardSales(){var r=NewRun();var room=Store(r);r.AddGold(1000);Assert.IsTrue(room.BuyItem(0));Assert.IsTrue(room.SellCard(r.Deck[0].InstanceId));var again=Store(r);Assert.AreSame(room.Visit,again.Visit);Assert.IsTrue(again.Visit.ItemOffers[0].Purchased);Assert.AreEqual(1,again.Visit.CardsSold);Assert.IsTrue(again.SellCard(r.Deck[0].InstanceId));Assert.AreEqual(8,r.Deck.Count);Assert.IsFalse(again.SellCard(r.Deck[0].InstanceId));}
 [Test] public void SaleLimitIsPerVisitAndNeverRemovesTooManyCards(){var r=NewRun();for(int i=0;i<4;i++)r.AddCard("W03");var room=Store(r);Assert.IsTrue(room.SellCard(r.Deck[0].InstanceId));Assert.IsTrue(room.SellCard(r.Deck[0].InstanceId));Assert.IsFalse(room.SellCard(r.Deck[0].InstanceId));var second=Store(r,id:"store2");Assert.IsTrue(second.SellCard(r.Deck[0].InstanceId));Assert.IsTrue(second.SellCard(r.Deck[0].InstanceId));Assert.AreEqual(10,r.Deck.Count);}
 [Test] public void SellingRemovesOnlyTheSelectedDuplicate(){var r=NewRun();var a=r.AddCard("W03");var b=r.AddCard("W03");var room=Store(r);Assert.IsTrue(room.SellCard(a.InstanceId));Assert.IsFalse(r.Deck.Contains(a));Assert.IsTrue(r.Deck.Contains(b));Assert.IsFalse(room.SellCard(a.InstanceId));}
 [Test] public void OverflowAndStaleRoomsCannotMutateInventory(){var r=NewRun();Give(r,"I01");var room=Store(r);r.AddGold(int.MaxValue);string card=r.Deck[0].InstanceId;Assert.IsFalse(room.SellCard(card));Assert.IsFalse(room.SellItem("I01"));Assert.AreEqual(10,r.Deck.Count);Assert.IsTrue(r.HasItem("I01"));r.ActiveRoom="other";Assert.IsFalse(room.BuyItem(0));Assert.IsFalse(room.Buy(0));}
 [Test] public void PendingAltarRewardMustBeClaimedBeforeTrading(){var r=NewRun();var room=Store(r);r.AddGold(1000);room.Visit.PendingAltarCards=new[]{"W03"};Assert.IsFalse(room.BuyItem(0));Assert.IsFalse(room.Buy(0));Assert.IsFalse(room.SellCard(r.Deck[0].InstanceId));Assert.IsTrue(room.ClaimAltarCard("W03"));Assert.IsTrue(room.BuyItem(0));}
 [Test] public void OriginalAltarTradesRemainSeparateFromShopping(){var r=NewRun();var room=Store(r);r.AddGold(1000);room.Visit.AltarTrades=new[]{AltarTrade.GoldForHealth};Assert.IsTrue(room.BuyItem(0));Assert.IsFalse(room.Visit.ChoiceMade);Assert.IsTrue(room.TradeAtAltar(AltarTrade.GoldForHealth));Assert.IsFalse(room.TradeAtAltar(AltarTrade.GoldForHealth));Assert.IsTrue(room.BuyItem(1));}
 [Test] public void SellingGrowthItemDestroysItsProgress(){var r=NewRun();Give(r,"I17");r.Items.Single().Progress=3;var room=Store(r);Assert.IsTrue(room.SellItem("I17"));Assert.IsTrue(r.AddItem("I17"));Assert.AreEqual(0,r.ItemProgress("I17"));}
 [Test] public void OpeningItemsCombineWithinHandAndEnergyLimits(){var r=NewRun(CharacterId.Warrior,Enumerable.Repeat("W01",10).ToArray());Give(r,"I01","I02","I03","I04","I17","I22","I35","I36","I39");r.Items.First(i=>i.ItemId=="I17").Progress=2;r.Items.First(i=>i.ItemId=="I22").Progress=4;r.Items.First(i=>i.ItemId=="I35").Progress=4;r.CurrentHP=r.MaxHP/2;r.ActiveRoom="r1";var b=new BattleRuntime(Modern(),r,DungeonRuntime.Node(r,"r1"));Assert.AreEqual(5,b.Strength);Assert.AreEqual(18,b.Block);Assert.AreEqual(4,b.Energy);Assert.AreEqual(6,b.Deck.Hand.Count);}
 [Test] public void LargeDeckOpeningItemRequiresEighteenCards(){var r=NewRun(CharacterId.Warrior,Enumerable.Repeat("W01",18).ToArray());Give(r,"I38");var b=Start(r);Assert.AreEqual(10,b.Block);}
 [Test] public void UniversalAttackSkillAndBlockEnginesUseCardCounts(){var r=NewRun(CharacterId.Warrior,"W01","W01","W01","W02","N12");Give(r,"I07","I08","I09","I10","I11");var b=Start(r);Play(b,"W01");Assert.AreEqual(9,b.LastCardResult.Damage);Play(b,"W01");Play(b,"W01");Assert.AreEqual(1,b.Strength);Assert.AreEqual(4,b.Block);Play(b,"W02");Assert.AreEqual(12,b.Block);Play(b,"N12");Assert.AreEqual(16,b.Block);}
 [Test] public void ExhaustPowerRefundAndThirdSkillEnginesDoNotRecurse(){var r=NewRun(CharacterId.Warrior,"W01","N06","N12","N12","N12","W13");Give(r,"I12","I13","I14","I15");r.CurrentHP-=10;var b=Start(r);int hp=r.CurrentHP;Play(b,"W01");Play(b,"N06");Assert.AreEqual(5,b.Block);Play(b,"N12");Play(b,"N12");Play(b,"N12");Assert.AreEqual(hp+3,r.CurrentHP);Assert.IsTrue(b.Deck.Hand.Any(c=>c.CardId=="W01"));b.Energy=3;Play(b,"W13");Assert.AreEqual(2,b.Energy);Assert.AreEqual(10,b.Block);}
 [TestCase(CharacterId.Warrior)] [TestCase(CharacterId.Mage)] [TestCase(CharacterId.Priest)] public void PoisonItemsFollowOnlyTheSelectedEnemyAndFirstUseLimit(CharacterId hero){var r=NewRun(hero,"N08","N08");Give(r,"I16","I40");var b=Start(r,1);var target=b.Enemies.Last();Play(b,"N08",target);Assert.AreEqual(5,target.Status.Poison);Play(b,"N08",target);Assert.AreEqual(8,target.Status.Poison);Assert.AreEqual(0,b.Enemy.Status.Poison);}
 [Test] public void WarriorItemsBridgeStrengthBlockSpendingAndRetention(){var r=NewRun(CharacterId.Warrior,"W03","W09","W16");Give(r,"I18","I19","I20","I21");var b=Start(r);Play(b,"W03");Assert.AreEqual(3,b.Block);b.Block=20;Play(b,"W09");Assert.AreEqual(34,b.LastCardResult.Damage);Assert.AreEqual(12,b.Block);Play(b,"W16");Assert.AreEqual(0,b.Block);b.Block=20;b.EndTurn();Assert.AreEqual(6,b.Block);}
 [Test] public void MageItemsUseOnlyTheirCorrespondingElementAndPaidResonance(){var r=NewRun(CharacterId.Mage,"M03","M04","M05","M10","M16","M08");Give(r,"I23","I24","I25","I26","I27","I28");var b=Start(r);Play(b,"M03");Assert.AreEqual(2,b.Strength);Assert.AreEqual(8,b.LastCardResult.Damage);Play(b,"M04");Assert.AreEqual(1,b.Enemy.Status.Weak);Assert.AreEqual(5,b.Block);Play(b,"M05");Assert.AreEqual(15,b.LastCardResult.Damage);Play(b,"M10");Assert.AreEqual(7,b.Block);Play(b,"M16");Assert.AreEqual(9,b.Block);Assert.AreEqual(4,b.Deck.Hand.Count);b.EndTurn();Assert.AreEqual(6,b.Energy);}
 [Test] public void PriestItemsConnectBrandActualHealingAndGraceWithoutLoops(){var r=NewRun(CharacterId.Priest,"P03","P10","P12");Give(r,"I29","I30","I31","I32","I33","I34");r.CurrentHP-=20;var b=Start(r,1);Assert.IsTrue(b.Enemies.All(e=>e.Status.Brand==2));Assert.AreEqual(2,b.Grace);int hp=r.CurrentHP;Play(b,"P03");Assert.AreEqual(3,b.Enemy.Status.Brand);Assert.AreEqual(4,b.Grace);Assert.AreEqual(4,b.Block);Assert.AreEqual(hp+2,r.CurrentHP);Play(b,"P10");Assert.AreEqual(5,b.Enemy.Status.Brand);Play(b,"P12");Assert.AreEqual(4,b.Grace);Assert.AreEqual(4,b.Block);}
 [Test] public void FullHealthDoesNotGenerateGraceOrHealingItemBlock(){var r=NewRun(CharacterId.Priest,"P12");Give(r,"I31","I32");var b=Start(r);Play(b,"P12");Assert.AreEqual(0,b.Grace);Assert.AreEqual(0,b.Block);}
 [Test] public void VictoryRewardsGrowOnceAndPersistIntoTheNextBattle(){var r=NewRun(CharacterId.Warrior,"W01");Give(r,"I05","I06","I17","I22","I35","I37");r.CurrentHP-=10;r.AddGold(100);var b=Start(r);int hp=r.CurrentHP;Kill(b);Assert.AreEqual(hp+3,r.CurrentHP);Assert.AreEqual(1,r.ItemProgress("I17"));Assert.AreEqual(2,r.ItemProgress("I22"));Assert.AreEqual(1,r.ItemProgress("I35"));int baseGold=b.Reward.BaseGold;Assert.AreEqual(100+baseGold+8+Math.Min(6,(100+baseGold+8)/20),r.Gold);int gold=r.Gold;var again=Start(r);Kill(again);Assert.AreEqual(gold,r.Gold);Assert.AreEqual(1,r.ItemProgress("I17"));Assert.AreEqual(2,r.ItemProgress("I22"));}
 [TestCase("r9")] [TestCase("boss")] public void EliteAndBossDropsAreUniqueScopedAndNotRepeated(string node){var r=NewRun(CharacterId.Warrior,"W01");var b=Start(r,node:node);Kill(b);Assert.AreEqual(1,r.Items.Count);string id=r.LastItemReward;Assert.IsNotNull(id);Assert.IsTrue(!Item40Catalog.Find(id).Owner.HasValue||Item40Catalog.Find(id).Owner==CharacterId.Warrior);var again=Start(r,node:node);Kill(again);Assert.AreEqual(1,r.Items.Count);}
 [Test] public void GrowthHasCapsAndNeverLeaksIntoANewRun(){var r=NewRun();Give(r,"I17","I22","I35");foreach(var item in r.Items){r.GrowItem(item.ItemId,100);Assert.AreEqual(Item40Catalog.Find(item.ItemId).GrowthCap,item.Progress);}Assert.AreEqual(0,NewRun().Items.Count);}
 [Test] public void ItemBlockDoesNotTriggerTheCardGuardTrainingPower(){var r=NewRun(CharacterId.Warrior,"N07","N06","W02");Give(r,"I13");var b=Start(r);Play(b,"N07");Assert.AreEqual(5,b.Block);Play(b,"N06");Assert.AreEqual(10,b.Block);Play(b,"W02");Assert.AreEqual(17,b.Block);}
 [Test] public void OncePerTurnRefundAndDamageBonusesResetOnTheNextTurn(){var r=NewRun(CharacterId.Warrior,"W01","W01","W09","W09");Give(r,"I07","I14");var b=Start(r);Play(b,"W01");Assert.AreEqual(9,b.LastCardResult.Damage);Play(b,"W01");Assert.AreEqual(6,b.LastCardResult.Damage);Play(b,"W09");Play(b,"W09");Assert.AreEqual(1,b.Energy);b.EndTurn();b.Energy=6;Play(b,"W01");Assert.AreEqual(9,b.LastCardResult.Damage);Play(b,"W09");Assert.AreEqual(4,b.Energy);}
 [Test] public void EveryCardAndUpgradeResolvesWithAllEligibleRelics(){var data=Modern();Assert.AreEqual(70,data.AllCards.Count);foreach(var definition in data.AllCards)foreach(int level in new[]{0,1}){var hero=definition.Owner??CharacterId.Warrior;string prefix=hero==CharacterId.Warrior?"W":hero==CharacterId.Mage?"M":"P";string other=definition.Id==prefix+"01"?prefix+"02":prefix+"01";var r=NewRun(hero,definition.Id,other);r.Deck.First(c=>c.CardId==definition.Id).UpgradeLevel=level;foreach(var item in Item40Catalog.All.Where(i=>!i.Owner.HasValue||i.Owner==hero))Assert.IsTrue(r.AddItem(item.Id));r.CurrentHP=r.MaxHP/2;var b=Start(r);b.Resonance=12;b.Grace=10;b.Enemy.Status.Brand=8;b.Block=20;b.Strength=3;var card=b.Deck.Hand.First(c=>c.CardId==definition.Id);var selection=new CardPlayOptions{SelectedInstance=b.Deck.Hand.First(c=>c.CardId==other).InstanceId};Assert.IsTrue(b.PlayCard(card.InstanceId,definition.RequiresEnemyTarget?b.Enemy.TargetId:null,options:selection),definition.Id+"/"+level);if(b.PendingDiscard)Assert.IsTrue(b.ResolveDiscard(b.Deck.Hand[0].InstanceId));Assert.That(b.Energy,Is.InRange(0,b.Data.Config.EnergyCap));Assert.GreaterOrEqual(b.Block,0);Assert.LessOrEqual(b.Resonance,12);Assert.LessOrEqual(b.Grace,10);}}
 [Test] public void StoreFillsAllFourSlotsWhenEveryClassItemIsAlreadyOwned(){var r=NewRun();foreach(var item in Item40Catalog.All.Where(i=>i.Owner==CharacterId.Warrior))Give(r,item.Id);var room=Store(r);Assert.AreEqual(4,room.Visit.ItemOffers.Count);Assert.IsTrue(room.Visit.ItemOffers.All(o=>!Item40Catalog.Find(o.ItemId).Owner.HasValue));}
 [Test] public void SellingAnItemRemovesItsNextBattleBonus(){var r=NewRun();Give(r,"I01");var room=Store(r);Assert.IsTrue(room.SellItem("I01"));var b=Start(r);Assert.AreEqual(0,b.Strength);}
 [Test] public void ZeroHalfBlockSpendDoesNotConsumeTheRecoveryTrigger(){var r=NewRun(CharacterId.Warrior,"W09","W09");Give(r,"I19");var b=Start(r);b.Block=1;Play(b,"W09");Assert.AreEqual(1,b.Block);b.Block=20;Play(b,"W09");Assert.AreEqual(12,b.Block);}
 [Test] public void FirstBrandBonusAlsoWorksWhenBrandAmplificationSeedsAnEmptyTarget(){var r=NewRun(CharacterId.Priest,"P17");Give(r,"I30");var b=Start(r);Play(b,"P17");Assert.AreEqual(3,b.Enemy.Status.Brand);}
 [Test] public void AllFortyItemsResolveAgainstTheActualSeventyCardRuntime(){foreach(var item in Item40Catalog.All){var hero=item.Owner??CharacterId.Warrior;string[] cards=hero==CharacterId.Mage?new[]{"M03","M04","M05","M10","M16","N08","N12","N06"}:hero==CharacterId.Priest?new[]{"P03","P10","P12","P07","N08","N12","N06"}:new[]{"W03","W08","W09","W16","W13","N08","N12","N06"};var r=NewRun(hero,cards);Give(r,item.Id);r.CurrentHP=r.MaxHP/2;var b=Start(r);foreach(string id in cards){b.Energy=6;b.Resonance=12;b.Block=Math.Max(b.Block,20);Play(b,id);Assert.That(b.Energy,Is.InRange(0,b.Data.Config.EnergyCap),item.Id);Assert.GreaterOrEqual(b.Block,0,item.Id);}Assert.IsTrue(b.EndTurn(),item.Id);}}
}
}
